<?php

declare(strict_types=1);

use AzGuard\Facades\AzGuard;
use AzGuard\Filament\Resources\RoleGrantResource\Pages\ListRoleGrants;
use AzGuard\Tests\Fixtures\Filament\BootsFilament;
use AzGuard\Tests\Fixtures\Filament\GrantWorld;
use AzGuard\Tests\TestCase;
use Filament\Actions\Testing\TestAction;
use Illuminate\Support\Facades\DB;
use Livewire\Livewire;

uses(TestCase::class, BootsFilament::class);

it('definition keys in the grant payload do not change the role catalogue', function (): void {
    GrantWorld::prepare();
    $this->bootFilament();
    GrantWorld::seed();
    GrantWorld::editor();

    $before = array_map(static fn ($role): array => [
        'key' => $role->key->key(),
        'class' => $role->class,
        'grantable' => $role->grantable,
        'super' => $role->superAdmin,
        'permissions' => array_map(static fn ($p) => $p->local(), $role->permissions),
    ], AzGuard::panel('admin')->roles()->all());

    Livewire::test(ListRoleGrants::class)
        ->callAction(TestAction::make('create')->table(), [
            'panel' => 'admin', 'subject' => 'user:2', 'key' => 'member', 'context_type' => '-',
            'class_name' => 'App\\Roles\\Forged', 'definition' => 'forged', 'permissions' => ['*'], 'superAdmin' => true,
        ]);

    $after = array_map(static fn ($role): array => [
        'key' => $role->key->key(),
        'class' => $role->class,
        'grantable' => $role->grantable,
        'super' => $role->superAdmin,
        'permissions' => array_map(static fn ($p) => $p->local(), $role->permissions),
    ], AzGuard::panel('admin')->roles()->all());

    $stored = (array) DB::table('azg_role_grants')->where('subject_id', '2')->first();

    file_put_contents('/tmp/p78-probe/r25.txt', json_encode([
        'catalogue_unchanged' => $before === $after,
        'stored_role' => $stored['role'] ?? null,
        'stored_has_class_column' => array_key_exists('class_name', $stored),
        'columns' => array_keys($stored),
    ], JSON_PRETTY_PRINT));

    expect($before)->toBe($after);
});
EOF
